(* [comment removed for export] *)
Definition atexit_stA (M : word -> option byte) (ax : PNST.bax) : Prop :=
  HAJ.atexit_cells segs M (pa_atexit A) (paa_atexit_f0 AA) (paa_atexit_a0 AA) (PNL.pn_drv_call AN) (PNL.pn_drv_guard AN) (paa_at_cxa_atexit AA) (PNST.bax_list A AN ax).   (* [comment removed for export] *)

Definition berr_okA (M : word -> option byte) (ax : PNST.bax) : Prop :=
