Lemma vstr_at_keep o x : 0 <= o -> o + 24 <= 2 ^ 64 -> ag (fst (vs_cells o x)) (snd (vs_cells o x)) -> dkr M M' o 24 ->
  (forall c n p, x = PM.VLong c n p -> dkr M M' p c) ->
  PM.vstr_at segs T3 M o x -> PM.vstr_at segs T3 M' o x.
