  MPST (p_more s) (p_done s) (p_depth s) src' (p_tb s) (p_tg s) bb' bg' (p_sb s) (p_sk s) (p_stk s).
Definition vec_rest_own (s : mpst) : list (Z * Z) := mvec_own (p_sb s) (p_sk s) ++ PM.vs_own (p_tb s).
