Definition src_owner (op ois lo hi : Z) (s : mpst) : PGS.owner :=
  {| PGS.ow_at := fun M src OB => mparser_at segs A acc ann vp_parser M op ois (with_src s src) /\ OB = mrest_own s;
     PGS.ow_os := op + OFF_SRC; PGS.ow_ois := ois; PGS.ow_lo := lo; PGS.ow_hi := hi;
     PGS.ow_win := fun M src OB p k => False |}.
Definition vec_owner (op ois lo hi : Z) (s : mpst) : PGV8.vowner :=
  {| PGV8.vw_at := fun M src x g OB => mparser_at segs A acc ann vp_parser M op ois (with_src_bb s src x g) /\ PGV8.v8_ok x g
                                        /\ OB = vec_rest_own s;
     PGV8.vw_os := op + OFF_SRC; PGV8.vw_ois := ois; PGV8.vw_ov := op + OFF_BB; PGV8.vw_lo := lo; PGV8.vw_hi := hi |}.
