Lemma bparser_set_more op ois s v :
  0 <= op -> op + PNM.PSIZE <= 2 ^ 64 -> bparser_at M op ois s -> own_below op s ->
  (forall a, op <= a < op + PNM.PSIZE -> X a -> op + 8 <= a < op + 9) ->
